func produce(n int) <-chan int {
	ch := make(chan int)
	go func() {
		for i := 1; i <= n; i++ {
			ch <- i     // each send waits for a receive
		}
		close(ch)       // signal 'no more values'
	}()
	return ch
}

func main() {
	sum := 0
	for v := range produce(4) { // drains until closed
		sum += v
	}
	fmt.Println(sum) // 1+2+3+4 = 10
}
